//! 2A03 frame counter core (nesdev, "APU Frame Counter").
//!
//! The sequence table lives in CPU cycles (`7457, 14913, 22371, 29828,
//! 29829, 29830` for the NTSC 4-step sequence; nesdev's APU-cycle values
//! 3728.5/7456.5/… doubled). [`FrameCounter::tick`] consumes one APU tick
//! (two CPU cycles) per call and returns the frame event due this tick,
//! which callers forward to the channels.
//!
//! NTSC only for now; PAL/Dendy step tables remain to be added.

/// Event generated by the frame sequencer.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum FrameEvent {
    /// No clock this tick.
    #[default]
    None,
    /// Quarter frame: envelopes (and the triangle's linear counter).
    Quarter,
    /// Half frame (also implies its quarter frame's work).
    Half,
}

/// The frame sequencer: quarter/half-frame clocks and the mode-0 IRQ flag.
#[derive(Debug, Clone)]
pub struct FrameCounter {
    /// `$4017`-bit 7: 4-step (false) or 5-step (true) sequence.
    five_step: bool,
    /// `$4017`-bit 6: IRQ inhibit.
    inhibit_irq: bool,
    /// Buffered `$4017` write settling 3–4 CPU cycles later.
    pending: Option<u8>,
    settle_delay: u8,
    step: usize,
    steps: [u32; 6],
    /// CPU cycles elapsed inside the current sequence.
    cpu_cycles: u32,
    irq_pending: bool,
}

impl Default for FrameCounter {
    fn default() -> Self {
        Self::new()
    }
}

impl FrameCounter {
    /// NTSC 4-step sequence, CPU cycles (nesdev table; the fractional
    /// half-cycle offsets round down to `±1` APU tick).
    const STEPS4_NTSC: [u32; 6] = [7457, 14913, 22371, 29828, 29829, 29830];
    /// NTSC 5-step sequence (interrupt is never set in this mode).
    const STEPS5_NTSC: [u32; 6] = [7457, 14913, 22371, 29829, 37281, 37282];
    /// Which event each step index generates (shared by both modes).
    const EVENT_AT_STEP: [FrameEvent; 6] = [
        FrameEvent::Quarter,
        FrameEvent::Half,
        FrameEvent::Quarter,
        FrameEvent::None,
        FrameEvent::Half,
        FrameEvent::None,
    ];

    /// Power-on state: 4-step mode, inhibit clear.
    #[must_use]
    pub const fn new() -> Self {
        Self {
            five_step: false,
            inhibit_irq: false,
            pending: None,
            settle_delay: 0,
            step: 0,
            steps: Self::STEPS4_NTSC,
            cpu_cycles: 0,
            irq_pending: false,
        }
    }

    /// `$4017`: mode and interrupt inhibit.
    ///
    /// The inhibit bit clears the pending IRQ immediately; the mode change
    /// (timer reset, and in 5-step mode an immediate quarter+half frame)
    /// lands 3–4 CPU cycles after the write, buffered here as a settle
    /// delay of two APU ticks.
    pub fn write(&mut self, val: u8) {
        self.pending = Some(val);
        self.settle_delay = 2;
        self.inhibit_irq = (val & 0x40) != 0;
        if self.inhibit_irq {
            self.irq_pending = false;
        }
    }

    /// One APU tick (two CPU cycles); returns the event due this tick.
    pub fn tick(&mut self) -> FrameEvent {
        let mut event = FrameEvent::None;
        if self.settle_delay > 0 {
            self.settle_delay -= 1;
            if self.settle_delay == 0
                && let Some(val) = self.pending.take()
            {
                self.apply_write(val, &mut event);
            }
        }

        self.cpu_cycles += 2;
        while self.cpu_cycles >= self.steps[self.step] {
            if !self.five_step && !self.inhibit_irq && self.step >= 3 {
                self.irq_pending = true;
            }
            let step_event = Self::EVENT_AT_STEP[self.step];
            if step_event == FrameEvent::Half {
                event = FrameEvent::Half;
            } else if step_event == FrameEvent::Quarter && event == FrameEvent::None {
                event = FrameEvent::Quarter;
            }
            self.step += 1;
            if self.step == self.steps.len() {
                self.step = 0;
                self.cpu_cycles = 0;
            }
        }
        event
    }

    /// Mode-0 IRQ flag, cleared by reading or by `$4017`-bit 6.
    #[must_use]
    pub const fn irq_pending(&self) -> bool {
        self.irq_pending
    }

    /// Clears the IRQ flag (the CPU's `$4015` read side effect).
    pub const fn clear_irq(&mut self) {
        self.irq_pending = false;
    }

    const fn apply_write(&mut self, val: u8, event: &mut FrameEvent) {
        self.five_step = (val & 0x80) != 0;
        self.steps = if self.five_step {
            Self::STEPS5_NTSC
        } else {
            Self::STEPS4_NTSC
        };
        self.step = 0;
        self.cpu_cycles = 0;
        // `$4017` with bit 7 set immediately generates a quarter+half frame
        // (nesdev side-effects note).
        if self.five_step {
            *event = FrameEvent::Half;
        }
    }
}
